1	import React from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
3	import { expect, userEvent, within } from 'storybook/test';
4	import { MemoryRouter } from 'react-router-dom';
5	import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
6	import { ZimmCartItemActions } from '.';
7	import type { WishlistMoveResult } from '.';
8	
9	const meta: Meta<typeof ZimmCartItemActions> = {
10	  title: 'Commerce/ZimmCartItemActions',
11	  component: ZimmCartItemActions,
12	  parameters: { layout: 'padded' },
13	  // ZimmCartItemActions renders ZimmLink, which calls useSafeHref() unconditionally (regional
14	  // link prefixing) — same provider shape zimmLink/index.stories.tsx uses for the useMultiSite()
15	  // this hook wraps. Identity buildUrl here since no story below asserts on prefixing.
16	  decorators: [
17	    (Story) => (
18	      <MemoryRouter>
19	        <MultiSiteProvider
20	          site={{ id: 'ZimmermannAU', alias: 'au' }}
21	          locale={{ id: 'en-AU', alias: 'en-AU' }}
22	          buildUrl={(path: string) => path}
23	        >
24	          <Story />
25	        </MultiSiteProvider>
26	      </MemoryRouter>
27	    ),
28	  ],
29	};
30	
31	export default meta;
32	
33	type Story = StoryObj<typeof ZimmCartItemActions>;
34	
35	const PRODUCT_NAME = 'Cloud 91 Small Clutch';
36	
