60	  args: {
61	    productId: 'product-abc',
62	    productName: PRODUCT_NAME,
63	    isGuest: false,
64	    onRemove: () => {},
65	    onMoveToWishlist: success,
66	    onGuestWishlistClick: () => {},
67	  },
68	  play: async ({ canvasElement }) => {
69	    const canvas = within(canvasElement);
70	    await userEvent.click(canvas.getByRole('button', { name: 'Move to Wishlist' }));
71	
72	    const doc = within(document.body);
73	    await expect(doc.findByText(`${PRODUCT_NAME} added to Wishlist`)).resolves.toBeInTheDocument();
74	  },
75	};
76	
77	export const AlreadyInWishlist: Story = {
78	  args: {
79	    productId: 'product-abc',
80	    productName: PRODUCT_NAME,
81	    isGuest: false,
82	    onRemove: () => {},
83	    onMoveToWishlist: alreadyInWishlist,
84	    onGuestWishlistClick: () => {},
85	  },
86	  play: async ({ canvasElement }) => {
87	    const canvas = within(canvasElement);
88	    await userEvent.click(canvas.getByRole('button', { name: 'Move to Wishlist' }));
89	
90	    const doc = within(document.body);
91	    await expect(doc.findByText('An item in your bag already exists in Wishlist')).resolves.toBeInTheDocument();
92	    // The item stays in the cart on this path (SFCC-272 AC6) — nothing in this story removes it,
93	    // there is simply no "item removed" state for a Storybook-isolated molecule to show.
94	  },
95	};
