import { chromium } from 'playwright';

const BASE = 'http://localhost:6006/iframe.html';
const STORIES = [
  'commerce-zimmcartemptystate--default',
  'commerce-zimmcartemptystate--at-non-au-site',
  'commerce-zimmcartemptystate--spans-both-drawer-columns-at-desktop',
];

const browser = await chromium.launch();

for (const id of STORIES) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const consoleErrors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('pageerror', (err) => consoleErrors.push(`pageerror: ${err.message}`));

  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(`${BASE}?id=${id}&viewMode=story`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);

  const errorBoundary = await page.locator('#error-message, .sb-errordisplay, #root [class*="error"]').count();
  const html = await page.locator('#storybook-root').innerHTML().catch(() => '<none>');

  console.log(`\n=== ${id} ===`);
  console.log('error boundary nodes:', errorBoundary);
  console.log('console/page errors:', JSON.stringify(consoleErrors));
  console.log('rendered html (first 400 chars):', html.slice(0, 400));

  if (id.includes('non-au-site')) {
    const link = page.getByRole('link', { name: 'Continue Shopping' });
    const href = await link.getAttribute('href');
    console.log('non-AU CTA href:', href);
  }

  if (id.includes('spans-both')) {
    const harness = page.getByTestId('grid-harness');
    const root = page.getByTestId('zimm-cart-empty-state');
    const harnessBox = await harness.boundingBox();
    const rootBox = await root.boundingBox();
    const computedGridColumn = await root.evaluate((el) => getComputedStyle(el).gridColumn);
    console.log('window width used:', 1440);
    console.log('harness box:', harnessBox);
    console.log('root box:', rootBox);
    console.log('computed gridColumn on root:', computedGridColumn);
  }

  await page.close();
}

await browser.close();

